SELECT ur.*, u.username AS reported_username FROM user_report ur LEFT JOIN sys_user u ON ur.reported_user_id = u.id
WHERE ur.status = #{status}
ORDER BY ur.created_at DESC

SELECT ur.*, u.username AS reported_username
FROM user_report ur
LEFT JOIN sys_user u ON ur.reported_user_id = u.id
WHERE ur.user_id = #{userId}

    AND ur.status = #{status}

ORDER BY ur.created_at DESC

